// Windows LANGID stores the primary language in its low ten bits; Russian is 0x19.
constexpr const char *defaultInterfaceLanguage(unsigned windowsUiLanguage) {
    return (windowsUiLanguage & 0x03ffu) == 0x0019u ? "ru" : "en";
}
